        """合并互相交叠的闭区间（端点相接也算交叠），返回按起点升序的元组列表；空输入返回 []。"""
        if not ranges:
            return []
        ordered = sorted((tuple(r) for r in ranges), key=lambda r: (r[0], r[1]))
